// reproduce-lh-hang.js
// Install dependencies with:
//   npm install lighthouse chrome-launcher

const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');

(async () => {
  // Launch a fresh headless Chrome
  const chrome = await chromeLauncher.launch({
    chromeFlags: [
      '--headless',
      '--disable-gpu',
      '--no-sandbox'
    ]
  });

  const options = {
    logLevel: 'info',
    port: chrome.port,
    onlyCategories: ['pwa'],         // audit only the PWA category
    skipAudits: []                   // don’t skip anything else
  };

  try {
    console.log('Launching Lighthouse audit...');
    const runnerResult = await lighthouse(
      'https://nicolas-hoizey.com/2017/01/how-much-data-should-my-service-worker-put-upfront-in-the-offline-cache.html',
      options
    );

    // If Lighthouse ever returns, print summary
    const lhr = runnerResult.lhr;
    console.log(`Lighthouse completed: score = ${lhr.categories.pwa.score}`);
  } catch (err) {
    console.error('Lighthouse threw an error:', err);
  } finally {
    await chrome.kill();
  }
})();
